begin;set local search_path=public,extensions;select plan(14);
select ok((select count(*)=4 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname in('clone_service_request','create_recurring_service_plan','transition_recurring_service_plan','generate_recurring_service_requests')and p.prosecdef),'four commands are security definer');
select ok(not has_function_privilege('anon','public.clone_service_request(uuid,date,text,text,uuid)','EXECUTE')and not has_function_privilege('service_role','public.generate_recurring_service_requests(uuid,date,integer,text,uuid)','EXECUTE'),'anon and service_role cannot execute commands');
select ok(not has_table_privilege('authenticated','public.recurring_service_plans','INSERT')and not has_table_privilege('authenticated','public.service_request_clone_provenance','UPDATE'),'authenticated cannot bypass commands or mutate provenance');
select ok((select relrowsecurity from pg_class where oid='public.service_request_clone_provenance'::regclass)and(select relrowsecurity from pg_class where oid='public.recurring_service_occurrences'::regclass),'tenant history has RLS');
select ok((select count(*)=3 from pg_trigger where not tgisinternal and tgname in('service_request_clone_provenance_immutable','recurring_service_plan_versions_immutable','recurring_service_occurrences_immutable')),'history is immutable');
select ok((select pg_get_constraintdef(oid)like'%MONTHLY%QUARTERLY%ANNUALLY%'from pg_constraint where conrelid='public.recurring_service_plan_versions'::regclass and contype='c'and pg_get_constraintdef(oid)like'%cadence%'),'cadence is limited to monthly quarterly annually');
select ok((select pg_get_constraintdef(oid)like'%ACTIVE%PAUSED%ENDED%'from pg_constraint where conrelid='public.recurring_service_plans'::regclass and contype='c'and pg_get_constraintdef(oid)like'%status%'),'plan lifecycle is constrained');
select ok((select count(*)=1 from pg_indexes where schemaname='public'and tablename='recurring_service_occurrences'and indexdef like'%UNIQUE%plan_id, scheduled_on%'),'one occurrence per plan and date');
select ok((select proconfig::text like'%search_path=pg_catalog%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='clone_request_core'),'clone core fixes search path');
select ok((select count(*)=4 from pg_policies where schemaname='public'and tablename in('service_request_clone_provenance','recurring_service_plans','recurring_service_plan_versions','recurring_service_occurrences')),'four restrictive read surfaces exist');
select ok(position('SERVICE_NOT_RECURRING_ELIGIBLE'in pg_get_functiondef('public.create_recurring_service_plan(uuid,text,date,date,text,text,uuid)'::regprocedure))>0,'non recurring services are refused');
select ok(position('RECURRING_GENERATION_BOUNDS_EXCEEDED'in pg_get_functiondef('public.generate_recurring_service_requests(uuid,date,integer,text,uuid)'::regprocedure))>0,'generation is bounded');
select ok(position('autonomous_invitations'in pg_get_functiondef('public.generate_recurring_service_requests(uuid,date,integer,text,uuid)'::regprocedure))>0 and position('autonomous_spend'in pg_get_functiondef('public.generate_recurring_service_requests(uuid,date,integer,text,uuid)'::regprocedure))>0,'generation explicitly creates no invitation or spend');
select ok(position('ServiceRequestClonedV2'in pg_get_functiondef('public.clone_service_request(uuid,date,text,text,uuid)'::regprocedure))>0 and position('RecurringServiceRequestsGeneratedV2'in pg_get_functiondef('public.generate_recurring_service_requests(uuid,date,integer,text,uuid)'::regprocedure))>0,'final clone and generation commands emit versioned Outbox events');
select*from finish();rollback;
